def group_migration(items, *, minimum: int = 1) -> dict:
    """Aggregate group rank migration between adjacent scales per region.

    ``items`` and ``minimum`` are validated exactly as in
    :func:`group_scale`, and the scale and region axes are generated the
    same way (first-appearance order, unique ``(scale, region)`` pairs);
    every ``result`` is a complete :func:`group_rank_stability` result
    (schema ``climate-grid/ggs-v1``) sharing the first item's
    ``reference`` and ``groups`` and ``scenarios`` axes.  At least two
    distinct scales must be present or ``ValueError`` is raised.

    The adjacent scale pairs follow the scale axis order.  For each
    region (in region order) and group (in group order), every adjacent
    pair is examined: when both results exist for the region and the
    group rows have a non-``None`` ``rank`` and ``uncertainty`` on both
    sides, ``d`` is the right rank minus the left rank and ``u`` is the
    ``hypot`` of the two uncertainties; otherwise both are ``None``.
    ``changes`` lists one ``[d, u]`` pair per adjacent scale pair and
    ``valid`` counts the valid pairs.

    When ``valid < minimum``, ``mean_abs``, ``uncertainty`` and
    ``rank`` are all ``None``; otherwise ``mean_abs`` is the sum of the
    absolute ``d`` values divided by ``valid`` and ``uncertainty`` is
    the ``hypot`` of every valid pair's ``u`` divided by ``valid``.
    Within each region the valid groups are ranked, from 1, by their
    unrounded ``mean_abs`` in ascending order; ties keep the group
    order.  Invalid groups follow in their original group order with
    ``rank`` of ``None``.

    The returned mapping uses the key order ``schema, scales, regions,
    reference, groups, data``; ``schema`` is ``climate-grid/gm-v1`` and
    ``reference`` and ``groups`` echo the first item's result
    unchanged.  ``data`` follows region order and, within each region,
    the ranking above; each row uses the key order ``region, group,
    valid, changes, mean_abs, uncertainty, rank``.  ``valid`` and a
    non-empty ``rank`` are ints; every output float is
    ``round(x, 12)`` with negative zero normalized to ``0.0`` and a
    non-finite derived value raises ``ValueError``.  The input is not
    modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 1:
        raise ValueError("items must be non-empty")

    scales: list[str] = []
    regions: list[str] = []
    seen_scales: set[str] = set()
    seen_regions: set[str] = set()
    seen_pairs: set[tuple[str, str]] = set()
    validated: dict[tuple[str, str], dict[str, dict]] = {}
    reference = ""
    groups: list[str] = []
    scenarios: list[str] = []
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _GROUP_MIGRATION_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys scale, region, result "
                "in order"
            )

        scale = item["scale"]
        if not isinstance(scale, str):
            raise TypeError(f"{where}.scale must be a str")
        if scale == "":
            raise ValueError(f"{where}.scale must be non-empty")

        region = item["region"]
        if not isinstance(region, str):
            raise TypeError(f"{where}.region must be a str")
        if region == "":
            raise ValueError(f"{where}.region must be non-empty")

        pair = (scale, region)
        if pair in seen_pairs:
            raise ValueError(
                f"duplicate items scale/region pair: "
                f"({scale!r}, {region!r})"
            )
        seen_pairs.add(pair)
        if scale not in seen_scales:
            seen_scales.add(scale)
            scales.append(scale)
        if region not in seen_regions:
            seen_regions.add(region)
            regions.append(region)

        item_reference, item_groups, item_scenarios, data = (
            _validate_group_rank_stability_result(
                item["result"], where=f"{where}.result"
            )
        )
        if not validated:
            reference = item_reference
            groups = item_groups
            scenarios = item_scenarios
        else:
            if item_reference != reference:
                raise ValueError(
                    "all items must share the same result reference, taken "
                    "from the first item"
                )
            if item_groups != groups:
                raise ValueError(
                    "all items must share the same result groups in the "
                    "same order, taken from the first item"
                )
            if item_scenarios != scenarios:
                raise ValueError(
                    "all items must share the same result scenarios in the "
                    "same order, taken from the first item"
                )

        validated[pair] = {row["group"]: row for row in data}

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    if len(scales) < 2:
        raise ValueError("at least two distinct scales are required")

    scale_pairs = [
        (scales[index], scales[index + 1])
        for index in range(len(scales) - 1)
    ]

    data_rows: list[dict] = []
    for region in regions:
        valid_rows: list[dict] = []
        invalid_rows: list[dict] = []
        for group in groups:
            changes: list[list] = []
            deltas: list[int] = []
            uncertainties: list[float] = []
            for left_scale, right_scale in scale_pairs:
                left = validated.get((left_scale, region))
                right = validated.get((right_scale, region))
                d = None
                u = None
                if left is not None and right is not None:
                    left_row = left[group]
                    right_row = right[group]
                    if (
                        left_row["rank"] is not None
                        and right_row["rank"] is not None
                        and left_row["uncertainty"] is not None
                        and right_row["uncertainty"] is not None
                    ):
                        try:
                            d = int(right_row["rank"]) - int(
                                left_row["rank"]
                            )
                            u = math.hypot(
                                float(left_row["uncertainty"]),
                                float(right_row["uncertainty"]),
                            )
                        except OverflowError:
                            raise ValueError(
                                f"derived statistics for group {group!r} "
                                "must be finite"
                            ) from None
                        if not _is_finite(u):
                            raise ValueError(
                                f"derived statistics for group {group!r} "
                                "must be finite"
                            )
                        deltas.append(d)
                        uncertainties.append(u)
                changes.append([d, _round_output(u) if u is not None else None])

            valid = len(deltas)
            base_row = {
                "region": region,
                "group": group,
                "valid": valid,
                "changes": changes,
            }
            if valid < minimum:
                invalid_rows.append(
                    {
                        **base_row,
                        "mean_abs": None,
                        "uncertainty": None,
                        "rank": None,
                    }
                )
                continue

            mean_abs_value = sum(abs(delta) for delta in deltas) / valid
            try:
                uncertainty_value = math.hypot(*uncertainties) / valid
            except OverflowError:
                raise ValueError(
                    f"derived statistics for group {group!r} must be finite"
                ) from None

            if (
                not _is_finite(mean_abs_value)
                or not _is_finite(uncertainty_value)
            ):
                raise ValueError(
                    f"derived statistics for group {group!r} must be finite"
                )

            valid_rows.append(
                {
                    **base_row,
                    "mean_abs_value": mean_abs_value,
                    "mean_abs": _round_output(mean_abs_value),
                    "uncertainty": _round_output(uncertainty_value),
                }
            )

        valid_rows.sort(key=lambda row: row["mean_abs_value"])
        for rank, row in enumerate(valid_rows, start=1):
            data_rows.append(
                {
                    "region": row["region"],
                    "group": row["group"],
                    "valid": row["valid"],
                    "changes": row["changes"],
                    "mean_abs": row["mean_abs"],
                    "uncertainty": row["uncertainty"],
                    "rank": rank,
                }
            )
        for row in invalid_rows:
            data_rows.append(row)

    return {
        "schema": _GROUP_MIGRATION_SCHEMA,
        "scales": scales,
        "regions": regions,
        "reference": reference,
        "groups": list(groups),
        "data": data_rows,
    }


_MIGRATION_CONSENSUS_SCHEMA = "climate-grid/gmc-v1"
_MIGRATION_CONSENSUS_ROW_KEYS = (
    "group",
    "covered",
    "signs",
    "agreement",
    "magnitude",
    "uncertainty",
    "rank",
)


def _validate_group_migration_result(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], str, list[str], list[dict]]:
    """Validate a complete :func:`group_migration` result.

    Returns the ``scales`` and ``regions`` axes, the ``reference``
    group, the ``groups`` axis and the flat ``data`` rows, checking the
    ``climate-grid/gm-v1`` contract: key order, the schema, the axes,
    the per-region ranked-then-unranked row order, each row's key order
    ``region, group, valid, changes, mean_abs, uncertainty, rank`` and
    every ``changes`` pair ``[d, u]``: the two members are non-``None``
    together, ``d`` is a non-bool int and ``u`` is a finite
    non-negative number rounded to 12 digits.  ``valid`` equals the
    number of non-``None`` pairs; ranked rows run consecutively from 1
    within each region, sorted by their unrounded ``mean_abs`` with the
    group order breaking ties, and precede the ``rank`` ``None`` rows,
    which keep the original group order.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _GROUP_MIGRATION_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, scales, "
            "regions, reference, groups, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _GROUP_MIGRATION_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_GROUP_MIGRATION_SCHEMA!r}"
        )

    scales = _validate_string_list(
        result["scales"], f"{where}.scales", minimum=2
    )
    regions = _validate_string_list(result["regions"], f"{where}.regions")

    reference = result["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

    groups = _validate_string_list(result["groups"], f"{where}.groups")
    if reference in groups:
        raise ValueError(
            f"{where}.reference must not appear in {where}.groups"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(regions) * len(groups):
        raise ValueError(
            f"{where}.data must contain exactly one row per "
            "(region, group) pair"
        )

    group_index = {group: index for index, group in enumerate(groups)}
    n_pairs = len(scales) - 1
    row_cursor = 0
    for region in regions:
        seen_groups: set[str] = set()
        rank_count = 0
        null_phase = False
        invalid_order = -1
        last_sort_key: tuple[float, int] | None = None
        for _ in range(len(groups)):
            row_where = f"{where}.data[{row_cursor}]"
            row = data[row_cursor]
            row_cursor += 1
            if not isinstance(row, dict):
                raise TypeError(f"{row_where} must be a dict")
            if tuple(row.keys()) != _GROUP_MIGRATION_ROW_KEYS:
                raise ValueError(
                    f"{row_where} must have exactly the keys region, "
                    "group, valid, changes, mean_abs, uncertainty, "
                    "rank in order"
                )

            if not isinstance(row["region"], str):
                raise TypeError(f"{row_where}.region must be a str")
            if row["region"] != region:
                raise ValueError(
                    f"{row_where}.region must be {region!r} for its "
                    "position"
                )

            group = row["group"]
            if not isinstance(group, str):
                raise TypeError(f"{row_where}.group must be a str")
            if group not in group_index:
                raise ValueError(
                    f"{row_where}.group {group!r} must appear in "
                    f"{where}.groups"
                )
            if group in seen_groups:
                raise ValueError(
                    f"{row_where}: group {group!r} appears more than "
                    "once for its region"
                )
            seen_groups.add(group)
            order = group_index[group]

            valid = row["valid"]
            if not isinstance(valid, int) or isinstance(valid, bool):
                raise TypeError(f"{row_where}.valid must be a non-bool int")
            if not 0 <= valid <= n_pairs:
                raise ValueError(
                    f"{row_where}.valid must be between 0 and the "
                    "number of adjacent scale pairs"
                )

            changes = row["changes"]
            if not isinstance(changes, list):
                raise TypeError(f"{row_where}.changes must be a list")
            if len(changes) != n_pairs:
                raise ValueError(
                    f"{row_where}.changes must contain one pair per "
                    "adjacent scale pair"
                )

            deltas: list[int] = []
            for c_index, pair in enumerate(changes):
                pair_where = f"{row_where}.changes[{c_index}]"
                if not isinstance(pair, list):
                    raise TypeError(f"{pair_where} must be a list")
                if len(pair) != 2:
                    raise ValueError(
                        f"{pair_where} must contain exactly 2 items"
                    )
                delta, pair_uncertainty = pair
                presence = [value is not None for value in pair]
                if not all(presence) and any(presence):
                    raise ValueError(
                        f"{pair_where}: d and u must be all None or "
                        "all present"
                    )
                if delta is None:
                    continue
                if not isinstance(delta, int) or isinstance(delta, bool):
                    raise TypeError(
                        f"{pair_where}[0] must be a non-bool int or None"
                    )
                _validate_number(
                    pair_uncertainty,
                    f"{pair_where}[1]",
                    nullable=False,
                )
                if pair_uncertainty < 0:
                    raise ValueError(
                        f"{pair_where}[1] must be non-negative"
                    )
                if pair_uncertainty != _round_output(pair_uncertainty):
                    raise ValueError(
                        f"{pair_where}[1] must be rounded to 12 digits"
                    )
                deltas.append(delta)

            if valid != len(deltas):
                raise ValueError(
                    f"{row_where}.valid must equal the number of "
                    "non-None change pairs"
                )

            mean_abs = row["mean_abs"]
            uncertainty = row["uncertainty"]
            rank = row["rank"]
            present = [value is not None for value in (mean_abs, uncertainty)]
            rank_present = rank is not None
            if any(present) and not all(present):
                raise ValueError(
                    f"{row_where}: mean_abs and uncertainty must be "
                    "all None or all present"
                )
            if any(present) != rank_present:
                raise ValueError(
                    f"{row_where}: mean_abs and uncertainty must be "
                    "present exactly when rank is not None"
                )
            if not rank_present:
                if null_phase and order <= invalid_order:
                    raise ValueError(
                        f"{row_where}: unranked rows must keep the "
                        "original group order"
                    )
                null_phase = True
                invalid_order = order
                continue

            if null_phase:
                raise ValueError(
                    f"{row_where}: ranked rows must precede rows with "
                    "rank None"
                )
            if not isinstance(rank, int) or isinstance(rank, bool):
                raise TypeError(
                    f"{row_where}.rank must be a non-bool int or None"
                )
            if valid < 1:
                raise ValueError(
                    f"{row_where}.valid must be positive when rank is "
                    "not None"
                )
            rank_count += 1
            if rank != rank_count:
                raise ValueError(
                    f"{row_where}.rank must run consecutively from 1"
                )
            _validate_number(
                mean_abs, f"{row_where}.mean_abs", nullable=False
            )
            if mean_abs < 0:
                raise ValueError(f"{row_where}.mean_abs must be non-negative")
            mean_abs_value = sum(abs(delta) for delta in deltas) / valid
            if mean_abs != _round_output(mean_abs_value):
                raise ValueError(
                    f"{row_where}.mean_abs must equal the mean absolute "
                    "change, rounded to 12 digits"
                )
            _validate_number(
                uncertainty, f"{row_where}.uncertainty", nullable=False
            )
            if uncertainty < 0:
                raise ValueError(
                    f"{row_where}.uncertainty must be non-negative"
                )
            if uncertainty != _round_output(uncertainty):
                raise ValueError(
                    f"{row_where}.uncertainty must be rounded to 12 digits"
                )
            sort_key = (mean_abs_value, order)
            if last_sort_key is not None and sort_key < last_sort_key:
                raise ValueError(
                    f"{row_where}: ranked rows must be ordered by "
                    "mean_abs with the group order breaking ties"
                )
            last_sort_key = sort_key

    return scales, regions, reference, groups, data


def migration_consensus(result, *, minimum: int = 1) -> dict:
    """Aggregate a cross-region migration consensus per group.

    ``result`` must be a complete :func:`group_migration` result
    (schema ``climate-grid/gm-v1``), validated against that contract.
    ``minimum`` must be a non-bool positive int.

    For every group (in the ``groups`` axis order) the region rows
    whose ``rank`` is not ``None`` are collected in region order:
    ``covered`` is their count and ``signs`` counts the non-``None``
    ``d`` values inside those rows' ``changes`` as a three-entry int
    list ``[negative, zero, positive]``.  When ``covered < minimum``,
    ``agreement``, ``magnitude``, ``uncertainty`` and ``rank`` are all
    ``None``.  Otherwise ``agreement`` is ``max(signs) / sum(signs)``,
    ``magnitude`` is the mean of the rows' ``mean_abs`` values and
    ``uncertainty`` is the ``hypot`` of the rows' ``uncertainty``
    values divided by ``covered``.

    The covered groups are ranked, from 1, by their unrounded
    ``magnitude`` in ascending order with the groups axis breaking
    ties; the uncovered groups follow in their original group order
    with ``rank`` of ``None``.

    The returned mapping uses the key order ``schema, scales, regions,
    reference, groups, data``; ``schema`` is ``climate-grid/gmc-v1`` and
    the axes echo the input.  ``data`` follows the ranking above; each
    row uses the key order ``group, covered, signs, agreement,
    magnitude, uncertainty, rank``.  ``covered``, the ``signs`` entries
    and a non-empty ``rank`` are ints; every output float is
    ``round(x, 12)`` with negative zero normalized to ``0.0`` and a
    non-finite derived value raises ``ValueError``.  The input is not
    modified.

    Raises ``TypeError`` for wrong container/argument types and
    ``ValueError`` for any other contract violation.
    """
    scales, regions, reference, groups, data = (
        _validate_group_migration_result(result)
    )

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    rows_by_group: dict[str, list[dict]] = {group: [] for group in groups}
    for row in data:
        rows_by_group[row["group"]].append(row)

    valid_rows: list[dict] = []
    invalid_rows: list[dict] = []
    for group in groups:
        covered_rows = [
            row for row in rows_by_group[group] if row["rank"] is not None
        ]
        covered = len(covered_rows)

        negative = zero = positive = 0
        magnitudes: list[float] = []
        uncertainties: list[float] = []
        for row in covered_rows:
            for delta, pair_uncertainty in row["changes"]:
                if delta is None:
                    continue
                if delta < 0:
                    negative += 1
                elif delta == 0:
                    zero += 1
                else:
                    positive += 1
            magnitudes.append(row["mean_abs"])
            uncertainties.append(row["uncertainty"])
        signs = [negative, zero, positive]

        base_row = {
            "group": group,
            "covered": covered,
            "signs": signs,
        }
        if covered < minimum:
            invalid_rows.append(
                {
                    **base_row,
                    "agreement": None,
                    "magnitude": None,
                    "uncertainty": None,
                    "rank": None,
                }
            )
            continue

        agreement_value = max(signs) / sum(signs)
        magnitude_value = sum(magnitudes) / covered
        try:
            uncertainty_value = math.hypot(*uncertainties) / covered
        except OverflowError:
            raise ValueError(
                f"derived statistics for group {group!r} must be finite"
            ) from None
        if (
            not _is_finite(agreement_value)
            or not _is_finite(magnitude_value)
            or not _is_finite(uncertainty_value)
        ):
            raise ValueError(
                f"derived statistics for group {group!r} must be finite"
            )

        valid_rows.append(
            {
                **base_row,
                "agreement": _round_output(agreement_value),
                "magnitude_value": magnitude_value,
                "magnitude": _round_output(magnitude_value),
                "uncertainty": _round_output(uncertainty_value),
            }
        )

    valid_rows.sort(key=lambda row: row["magnitude_value"])
    data_rows: list[dict] = []
    for rank, row in enumerate(valid_rows, start=1):
        data_rows.append(
            {
                "group": row["group"],
                "covered": row["covered"],
                "signs": row["signs"],
                "agreement": row["agreement"],
                "magnitude": row["magnitude"],
                "uncertainty": row["uncertainty"],
                "rank": rank,
            }
        )
    for row in invalid_rows:
        data_rows.append(row)

    return {
        "schema": _MIGRATION_CONSENSUS_SCHEMA,
        "scales": list(scales),
        "regions": list(regions),
        "reference": reference,
        "groups": list(groups),
        "data": data_rows,
    }

"""Scenario downscaling of reconstructed daily climate grids."""

from __future__ import annotations

import datetime
import math
import re
from typing import Any

from .regional import (
    _coverage_window_region,
    _entropy_window_region,
    _exceedance_window_region,
    _histogram_window_region,
    _quantile_window_region,
    _validate_quantiles as _regional_validate_quantiles,
    _validate_regions,
    _validate_windows,
    _window_region,
)

_SCHEMA = "climate-grid/scenario-v1"
_TEMPORAL_SCHEMA = "climate-grid/temporal-v1"
_TEMPORAL_KEYS = frozenset({"schema", "times", "lats", "lons", "data"})
_SERIES_KEYS = frozenset({"values", "status", "uncertainty"})
_STATUSES = frozenset({"observed", "interpolated", "missing"})
_MODES = frozenset({"additive", "multiplicative"})
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _is_finite(value: Any) -> bool:
    try:
        return math.isfinite(value)
    except OverflowError:
        # Huge ints cannot be represented as finite floats.
        return False


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where} must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where} must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"{where} must be a valid Gregorian date") from None


def _validate_axis(axis: Any, name: str) -> None:
    if not isinstance(axis, list):
        raise TypeError(f"{name} must be a list")
    if len(axis) == 0:
        raise ValueError(f"{name} must be non-empty")
    for index, value in enumerate(axis):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                f"{name}[{index}] must be a finite non-bool int or float"
            )
        if not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be finite")
    for index in range(1, len(axis)):
        if axis[index] <= axis[index - 1]:
            raise ValueError(f"{name} must be strictly increasing")


def _validate_number(cell: Any, target: str, *, nullable: bool) -> None:
    if nullable and cell is None:
        return
    if not isinstance(cell, (int, float)) or isinstance(cell, bool):
        raise TypeError(f"{target} must be a number" + (" or None" if nullable else ""))
    if not _is_finite(cell):
        raise ValueError(f"{target} must be finite")


def _validate_temporal(
    temporal: Any, *, schema: str = _TEMPORAL_SCHEMA, where: str = "temporal"
) -> tuple[list[str], list, list, dict]:
    if not isinstance(temporal, dict):
        raise TypeError(f"{where} must be a dict")
    if set(temporal.keys()) != _TEMPORAL_KEYS:

def _validate_scale_rank_consensus_result(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list]:
    """Validate a complete :func:`scale_rank_consensus` result.

    Returns the ``scenarios`` axis and the ``data`` rows, checking the
    full ``climate-grid/rh-consensus-v1`` generation contract: key
    order, the echoed axes, positional scenario matching, the
    ``count``/``coverage`` bounds and their recomputed relationship,
    the all-``None`` or all-present ``mean_rank, dispersion,
    stability_change, interval`` invariant and the recomputation of
    ``dispersion`` (and the rounding) of every present row.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _SCALE_RANK_CONSENSUS_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, scales, "
            "names, reference, scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _SCALE_RANK_CONSENSUS_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_SCALE_RANK_CONSENSUS_SCHEMA!r}"
        )

    scales = _validate_string_list(
        result["scales"], f"{where}.scales", minimum=2
    )
    names = _validate_string_list(
        result["names"], f"{where}.names", minimum=2
    )

    reference = result["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

    scenarios = _validate_string_list(
        result["scenarios"], f"{where}.scenarios", minimum=0
    )
    if reference in scenarios:
        raise ValueError(
            f"{where}.scenarios must not contain the reference "
            f"scenario {reference!r}"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(scenarios):
        raise ValueError(
            f"{where}.data must contain exactly one row per scenario"
        )

    n_scales = len(scales)
    n_scenarios = len(scenarios)
    for row_index, row in enumerate(data):
        row_where = f"{where}.data[{row_index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _SCALE_RANK_CONSENSUS_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys scenario, "
                "count, coverage, mean_rank, dispersion, "
                "stability_change, interval in order"
            )

        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario != scenarios[row_index]:
            raise ValueError(
                f"{row_where}.scenario {scenario!r} must equal "
                f"{where}.scenarios[{row_index}] "
                f"({scenarios[row_index]!r})"
            )

        count = row["count"]
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(f"{row_where}.count must be a non-bool int")
        if not 0 <= count <= n_scales:
            raise ValueError(
                f"{row_where}.count must be between 0 and the number "
                "of scales"
            )

        coverage = row["coverage"]
        _validate_number(coverage, f"{row_where}.coverage", nullable=False)
        if not 0 <= coverage <= 1:
            raise ValueError(
                f"{row_where}.coverage must be between 0 and 1"
            )
        if coverage != _round_output(count / n_scales):
            raise ValueError(
                f"{row_where}.coverage must equal count divided by "
                "the number of scales"
            )

        mean_rank = row["mean_rank"]
        dispersion = row["dispersion"]
        stability_change = row["stability_change"]
        interval = row["interval"]
        members = (mean_rank, dispersion, stability_change, interval)
        present = [value is not None for value in members]
        if any(present) and not all(present):
            raise ValueError(
                f"{row_where}: mean_rank, dispersion, "
                "stability_change and interval must be all None or "
                "all present"
            )
        if not any(present):
            continue

        if count < 1:
            raise ValueError(
                f"{row_where}.count must be positive when mean_rank, "
                "dispersion, stability_change and interval are present"
            )

        _validate_number(
            mean_rank, f"{row_where}.mean_rank", nullable=False
        )
        if not 1 <= mean_rank <= n_scenarios:
            raise ValueError(
                f"{row_where}.mean_rank must be a valid scenario rank"
            )
        if mean_rank != _round_output(mean_rank):
            raise ValueError(
                f"{row_where}.mean_rank must be rounded to 12 digits"
            )

        _validate_number(
            dispersion, f"{row_where}.dispersion", nullable=False
        )
        if dispersion < 0:
            raise ValueError(
                f"{row_where}.dispersion must be non-negative"
            )

        _validate_number(
            stability_change,
            f"{row_where}.stability_change",
            nullable=False,
        )
        if not -1 <= stability_change <= 1:
            raise ValueError(
                f"{row_where}.stability_change must be between -1 and 1"
            )
        if stability_change != _round_output(stability_change):
            raise ValueError(
                f"{row_where}.stability_change must be rounded to "
                "12 digits"
            )

        if not isinstance(interval, list):
            raise TypeError(f"{row_where}.interval must be a list")
        if len(interval) != 2:
            raise ValueError(
                f"{row_where}.interval must contain exactly 2 items"
            )
        _validate_number(
            interval[0], f"{row_where}.interval[0]", nullable=False
        )
        _validate_number(
            interval[1], f"{row_where}.interval[1]", nullable=False
        )
        if not 1 <= interval[0] <= interval[1] <= n_scenarios:
            raise ValueError(
                f"{row_where}.interval bounds must be valid ranks "
                "with the lower bound first"
            )
        if interval[0] != _round_output(interval[0]) or interval[
            1
        ] != _round_output(interval[1]):
            raise ValueError(
                f"{row_where}.interval bounds must be rounded to "
                "12 digits"
            )
        expected_dispersion = _round_output(
            (interval[1] - interval[0]) / 2
        )
        if dispersion != expected_dispersion:
            raise ValueError(
                f"{row_where}.dispersion must equal half the "
                "interval width"
            )

    return scenarios, data


